Q: How to set autofocus only in xaml? A: <blockquote>
<p>is there  any way, to make this without a name?</p>
</blockquote>
<p>if you use MVVM, - can Bind <strong>Custom Attached Property</strong> to a boolean property of your certain textbox.
Your Attached Property can look like this (copied from search):</p>
<pre><code>public static class FocusBehavior
{
    public static readonly DependencyProperty FocusedProperty =
        DependencyProperty.RegisterAttached(
            &quot;Focused&quot;, typeof(bool), typeof(FocusBehavior),
            new PropertyMetadata(false, OnFocusedChanged));

    public static bool GetFocused(DependencyObject obj) =&gt; (bool)obj.GetValue(FocusedProperty);
    public static void SetFocused(DependencyObject obj, bool value) =&gt; obj.SetValue(FocusedProperty, value);

    private static void OnFocusedChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is UIElement element &amp;&amp; (bool)e.NewValue)
        {
            element.Focus();
        }
    }
}
</code></pre>
<p>with binding in <code>xaml</code> like this:
<code>&lt;TextBox Text=&quot;{Binding InputText}&quot;  local:FocusBehavior.Focused=&quot;{Binding ShouldFocusTextBox}&quot; /&gt;</code></p>

Q: Dynamic column header in datatable from json array A: <p>This code worked for me.</p>
<p>I was getting an issue in the console with your code.</p>
<p><em>Uncaught TypeError: Cannot read properties of undefined (reading 'aDataSort')</em></p>
<p>Then I modified the code according to the code below.</p>
<p>I used THEAD with TR</p>
<p>And added few properties, and code worked</p>
<p><strong>Output</strong></p>
<p><a href="https://i.sstatic.net/9nS08cJK.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/9nS08cJK.png" alt="enter image description here" /></a></p>
<p><strong>Workable Code</strong></p>
<pre><code>&lt;html&gt;
&lt;head&gt;
     &lt;link rel=&quot;stylesheet&quot; type=&quot;text/css&quot; href=&quot;https://cdn.datatables.net/1.11.3/css/jquery.dataTables.min.css&quot;&gt;

&lt;/head&gt;
&lt;body&gt;
     &lt;table id=&quot;example&quot; class=&quot;display&quot; cellspacing=&quot;0&quot; width=&quot;100%&quot; border=&quot;1&quot;&gt;
   &lt;thead&gt;
     &lt;tr&gt;&lt;/tr&gt;
   &lt;/thead&gt;
 &lt;/table&gt;
     &lt;script type=&quot;text/javascript&quot; src=&quot;https://code.jquery.com/jquery-3.5.1.js&quot;&gt;&lt;/script&gt;
    &lt;script type=&quot;text/javascript&quot; src=&quot;https://cdn.datatables.net/1.11.3/js/jquery.dataTables.min.js&quot;&gt;&lt;/script&gt;
    &lt;script type=&quot;text/javascript&quot;&gt;
        var JSONResult = '{&quot;column1&quot;:&quot;data1&quot;,&quot;column2&quot;:&quot;data2&quot;,&quot;column3&quot;:&quot;data3&quot;,&quot;columnN&quot;:&quot;dataN&quot;}';
        var row_dtable = new Array();
        var dtable_api = $('#example').dataTable({

            bSort: false,
            aoColumns: [ { sWidth: &quot;45%&quot; }, { sWidth: &quot;45%&quot; }, { sWidth: &quot;10%&quot;, bSearchable: false, bSortable: false } ],
        &quot;scrollY&quot;:        &quot;200px&quot;,
        &quot;scrollCollapse&quot;: true,
        &quot;info&quot;:           true,
        &quot;paging&quot;:         true
        });

            $.each(JSON.parse(JSONResult) , function(key, value) {
                row_dtable.push(value);
            });     
            dtable_api.api().row.add(row_dtable).draw(false);  
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>
